import{readFileSync}from'node:fs';
import{pathToFileURL}from'node:url';
// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  if(!Array.isArray(edits))throw Error('edits must be an array');
  for(const edit of edits)checkEdit(source,edit);
  const ranges=[],insertions=[];
  for(const edit of edits){
    if(edit.start===edit.end)insertions.push({pos:edit.start,text:edit.after});
    else ranges.push({start:edit.start,end:edit.end,text:edit.after});
  }
  for(let i=0;i<ranges.length;i++)
    for(let j=i+1;j<ranges.length;j++){
      const a=ranges[i],b=ranges[j];
      if(a.start<b.end&&b.start<a.end)throw Error('overlapping edit ranges');
    }
  for(let i=0;i<insertions.length;i++)
    for(let j=i+1;j<insertions.length;j++)
      if(insertions[i].pos===insertions[j].pos)throw Error('insertions at the same position');
  for(const insertion of insertions)
    for(const range of ranges)
      if(insertion.pos>=range.start&&insertion.pos<=range.end)
        throw Error('insertion inside an edited range');
  const ops=[];
  for(const range of ranges)ops.push({pos:range.start,end:range.end,text:range.text});
  for(const insertion of insertions)ops.push({pos:insertion.pos,end:insertion.pos,text:insertion.text});
  ops.sort((a,b)=>a.pos-b.pos);
  let text='',cursor=0;
  for(const op of ops){
    text+=source.slice(cursor,op.pos)+op.text;
    cursor=op.end;
  }
  text+=source.slice(cursor);
  return{text,applied:edits.length};
}
// Add the JSON-file CLI described by the work order without import side effects.
if(process.argv[1]!==undefined&&import.meta.url===pathToFileURL(process.argv[1]).href){
  const fail=(message)=>{
    process.stderr.write(`${message}\n`);
    process.exit(2);
  };
  if(process.argv.length!==3)fail('usage: node patch-transaction.js INPUT_JSON_FILE');
  let raw;
  try{
    raw=readFileSync(process.argv[2],'utf8');
  }catch(error){
    fail(`cannot read input file: ${error.message}`);
  }
  let doc;
  try{
    doc=JSON.parse(raw);
  }catch(error){
    fail(`invalid JSON: ${error.message}`);
  }
  try{
    const result=applyTransaction(typeof doc==='object'&&doc!==null?doc.source:undefined,
      typeof doc==='object'&&doc!==null?doc.edits:undefined);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  }catch(error){
    fail(error.message);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync,writeFileSync}from'node:fs';
import {tmpdir}from'node:os';
import {join}from'node:path';
import {execFileSync,spawnSync}from'node:child_process';
import {applyEdit,applyTransaction}from'../patch-transaction.js';
const edit=(start,end,before,after,extra)=>{
  const e={start,end,before,after};
  if(extra)Object.assign(e,extra);
  return e;
};
const cli=(...args)=>spawnSync(process.execPath,
  [new URL('../patch-transaction.js',import.meta.url).pathname,...args],{encoding:'utf8'});
test('no-op edits are valid, count, and may repeat or be adjacent',()=>{
  const source='abcdef';
  assert.deepEqual(applyTransaction(source,[edit(2,2,'','')]),{text:'abcdef',applied:1});
  assert.deepEqual(applyTransaction(source,[edit(2,4,'cd','cd')]),{text:'abcdef',applied:1});
  assert.deepEqual(applyTransaction(source,[edit(2,2,'',''),edit(2,2,'','')]),
    {text:'abcdef',applied:2});
  assert.deepEqual(applyTransaction(source,[edit(2,2,'','x'),edit(2,2,'','y')]),
    {text:'abcdef',applied:2});
  assert.deepEqual(applyTransaction(source,[edit(2,4,'cd','x'),edit(2,4,'cd','x')]),
    {text:'abxf',applied:2});
});
test('unknown fields are ignored and values are not coerced',()=>{
  assert.deepEqual(applyTransaction('abc',[edit(0,1,'a','Z',
    {id:7,note:'x',tag:['a',1],object:{},bool:true})]),{text:'Zbc',applied:1});
  assert.throws(()=>applyTransaction('abc',[{start:'0',end:1,before:'a',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:1,before:'a',after:1}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:1,before:'a'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:1,after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:-0.5,end:1,before:'a',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:1.5,before:'a',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:9e20,end:9e20,before:'',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:0,end:9e20,before:'',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:null,end:null,before:null,after:null}]),Error);
  assert.throws(()=>applyTransaction('abc',[{end:0,start:1,before:'a',after:'Z'}]),Error);
  assert.throws(()=>applyTransaction('abc',[{start:3,end:4,before:'a',after:'Z'}]),Error);
  assert.throws(()=>applyEdit('abc',null),Error);
  assert.throws(()=>applyEdit('abc',[edit(0,1,'a','Z')]),Error);
  assert.throws(()=>applyEdit('abc',NaN),Error);
});
test('range overlap rejection and boundary behavior',()=>{
  assert.throws(()=>applyTransaction('abcdef',[edit(0,2,'ab','x'),edit(1,3,'bc','y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(0,3,'abc','x'),edit(1,2,'b','y')]),Error);
  assert.throws(()=>applyTransaction('abcdef',[edit(1,2,'b','x'),edit(0,3,'abc','y')]),Error);
  assert.deepEqual(applyTransaction('abcdef',[edit(0,2,'ab','x'),edit(2,4,'cd','y')]),
    {text:'xyef',applied:2});
  assert.throws(()=>applyTransaction('abcdef',[edit(0,4,'abcd','x'),edit(4,6,'ef','y')]),
    null);
  assert.deepEqual(applyTransaction('abcdef',[edit(4,6,'ef','y'),edit(0,4,'abcd','x')]),
    {text:'xy',applied:2});
});
test('insertion conflict rules',()=>{
  assert.throws(()=>applyTransaction('abcd',[edit(2,2,'','x'),edit(2,2,'','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(2,2,'','x'),edit(2,2,'','')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(2,2,'','x'),edit(0,2,'ab','y')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(0,2,'ab','y'),edit(2,2,'','x')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(0,2,'ab','y'),edit(1,1,'','x')]),Error);
  assert.throws(()=>applyTransaction('abcd',[edit(1,1,'','x'),edit(2,4,'cd','y')]),Error);
  assert.deepEqual(applyTransaction('abcd',[edit(0,2,'ab','x'),edit(3,3,'','y')]),
    {text:'xaycd',applied:2});
  assert.deepEqual(applyTransaction('abcd',[edit(3,3,'','y'),edit(4,4,'','z')]),
    {text:'abcdez',applied:2});
  assert.deepEqual(applyTransaction('abc',[edit(0,0,'','y'),edit(3,3,'','z')]),
    {text:'yabcz',applied:2});
  assert.deepEqual(applyTransaction('abc',[edit(1,1,'','x'),edit(2,2,'','y')]),
    {text:'axbzc',applied:2});
  assert.throws(()=>applyTransaction('abc',[edit(0,3,'abc','x'),edit(0,0,'','y')]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(0,3,'abc','x'),edit(1,1,'','y')]),Error);
});
test('result is order independent and preserves untouched content',()=>{
  const source='a\rb\nc\nd\ne';
  const edits=[edit(1,3,'\rb','X'),edit(0,1,'a','Z'),edit(5,5,'','!')];
  for(const order of[edits,[...edits].reverse(),[edits[1],edits[2],edits[0]]])
    assert.deepEqual(applyTransaction(source,order),{text:'Z\nc\nd\ne!',applied:3});
  const surrogate='abc\ud800\udc00def';
  assert.deepEqual(applyTransaction(surrogate,[edit(3,5,'\ud800\udc00','Q')]),
    {text:'abcQdef',applied:1});
  const crlf='one\r\ntwo\r\nthree';
  assert.deepEqual(applyTransaction(crlf,[edit(0,3,'one','ONE'),edit(4,7,'two','TWO')]),
    {text:'ONE\r\nTWO\r\nthree',applied:2});
  assert.deepEqual(applyTransaction('',[edit(0,0,'','x')]),{text:'x',applied:1});
  assert.throws(()=>applyTransaction('',[edit(0,0,'','x'),edit(0,0,'','y')]),Error);
});
test('input array and objects are not mutated',()=>{
  const original=edit(0,1,'a','Z');
  const snapshot=JSON.parse(JSON.stringify(original));
  const edits=[original,edit(2,3,'c','Y')];
  applyTransaction('abc',edits);
  assert.deepEqual(edits,JSON.parse(JSON.stringify([snapshot,edit(2,3,'c','Y')])));
  assert.deepEqual(original,snapshot);
});
test('transaction argument validation',()=>{
  assert.throws(()=>applyTransaction(null,[]),Error);
  assert.throws(()=>applyTransaction(1,[]),Error);
  assert.throws(()=>applyTransaction('abc',null),Error);
  assert.throws(()=>applyTransaction('abc',{}),Error);
  assert.throws(()=>applyTransaction('abc','x'),Error);
  assert.throws(()=>applyTransaction('abc',[null]),Error);
  assert.throws(()=>applyTransaction('abc',[[]]),Error);
  assert.throws(()=>applyTransaction('abc',['x']),Error);
  assert.throws(()=>applyTransaction('abc',[NaN]),Error);
  assert.throws(()=>applyTransaction('abc',[edit(0,1,'a','Z'),{start:5,end:6,before:'z',after:'q'}]),Error);
  assert.deepEqual(applyTransaction('abc',[]),{text:'abc',applied:0});
});
test('CLI success, argument, file, JSON, and transaction failures',()=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-tx-'));
  const okFile=join(dir,'ok.json');
  writeFileSync(okFile,JSON.stringify({note:'ignored',source:'abcdef',
    edits:[edit(0,1,'a','LONG'),edit(3,5,'de','X')]}));
  const good=cli(okFile);
  assert.equal(good.status,0);
  assert.equal(good.stderr,'');
  assert.equal(good.stdout,'{"text":"LONGbcXf","applied":2}\n');
  const emptyFile=join(dir,'empty.json');
  writeFileSync(emptyFile,JSON.stringify({source:'tail\r\n',edits:[]}));
  const empty=cli(emptyFile);
  assert.equal(empty.status,0);
  assert.equal(empty.stderr,'');
  assert.equal(empty.stdout,'{"text":"tail\\r\\n","applied":0}\n');
  const missing=cli(join(dir,'missing.json'));
  assert.equal(missing.status,2);
  assert.equal(missing.stdout,'');
  assert.ok(missing.stderr.length>0);
  const badArgs0=cli();
  assert.equal(badArgs0.status,2);
  assert.equal(badArgs0.stdout,'');
  assert.ok(badArgs0.stderr.length>0);
  const badArgs2=cli(okFile,okFile);
  assert.equal(badArgs2.status,2);
  assert.equal(badArgs2.stdout,'');
  assert.ok(badArgs2.stderr.length>0);
  const badJson=join(dir,'bad.json');
  writeFileSync(badJson,'{source: 1');
  const badJsonOut=cli(badJson);
  assert.equal(badJsonOut.status,2);
  assert.equal(badJsonOut.stdout,'');
  assert.ok(badJsonOut.stderr.length>0);
  const badTx=join(dir,'badtx.json');
  writeFileSync(badTx,JSON.stringify({source:'abc',
    edits:[{start:1,end:1,before:'',after:'x'},{start:1,end:2,before:'b',after:'y'}]}));
  const badTxOut=cli(badTx);
  assert.equal(badTxOut.status,2);
  assert.equal(badTxOut.stdout,'');
  assert.ok(badTxOut.stderr.length>0);
  const badSource=join(dir,'badsrc.json');
  writeFileSync(badSource,JSON.stringify({source:123,edits:[]}));
  const badSourceOut=cli(badSource);
  assert.equal(badSourceOut.status,2);
  assert.equal(badSourceOut.stdout,'');
  assert.ok(badSourceOut.stderr.length>0);
  rmSync(dir,{recursive:true,force:true});
});
test('importing the module does not run the CLI',()=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-tx-import-'));
  const file=join(dir,'ok.json');
  writeFileSync(file,JSON.stringify({source:'abc',edits:[]}));
  const out=execFileSync(process.execPath,
    ['-e',`import{applyTransaction}from'../patch-transaction.js';
      console.log(JSON.stringify(applyTransaction('abc',[])));`,
      file],{cwd:new URL('..',import.meta.url).pathname,encoding:'utf8'});
  assert.equal(out,'{"text":"abc","applied":0}\n');
  rmSync(dir,{recursive:true,force:true});
});

