import{readFileSync}from'node:fs';
import{pathToFileURL}from'node:url';
// The existing single-edit API works. Preserve it while extending this module.
function checkEdit(source,edit){
  if(typeof source!=='string'||edit===null||typeof edit!=='object'||Array.isArray(edit)
    ||!Number.isSafeInteger(edit.start)||!Number.isSafeInteger(edit.end)
    ||edit.start<0||edit.start>edit.end||edit.end>source.length
    ||typeof edit.before!=='string'||typeof edit.after!=='string')throw Error('invalid edit');
  if(source.slice(edit.start,edit.end)!==edit.before)throw Error('preimage mismatch');
}
export function applyEdit(source,edit){
  checkEdit(source,edit);
  return source.slice(0,edit.start)+edit.after+source.slice(edit.end);
}
export function applyTransaction(source,edits){
  if(typeof source!=='string')throw Error('source must be a string');
  if(!Array.isArray(edits))throw Error('edits must be an array');
  for(const edit of edits)checkEdit(source,edit);
  const ranges=[],insertions=[];
  for(const edit of edits){
    if(edit.start===edit.end)insertions.push({pos:edit.start,text:edit.after});
    else ranges.push({start:edit.start,end:edit.end,text:edit.after});
  }
  for(let i=0;i<ranges.length;i++)
    for(let j=i+1;j<ranges.length;j++){
      const a=ranges[i],b=ranges[j];
      if(a.start<b.end&&b.start<a.end)throw Error('overlapping edit ranges');
    }
  for(let i=0;i<insertions.length;i++)
    for(let j=i+1;j<insertions.length;j++)
      if(insertions[i].pos===insertions[j].pos)throw Error('insertions at the same position');
  for(const insertion of insertions)
    for(const range of ranges)
      if(insertion.pos>=range.start&&insertion.pos<=range.end)
        throw Error('insertion inside an edited range');
  const ops=[];
  for(const range of ranges)ops.push({pos:range.start,end:range.end,text:range.text});
  for(const insertion of insertions)ops.push({pos:insertion.pos,end:insertion.pos,text:insertion.text});
  ops.sort((a,b)=>a.pos-b.pos);
  let text='',cursor=0;
  for(const op of ops){
    text+=source.slice(cursor,op.pos)+op.text;
    cursor=op.end;
  }
  text+=source.slice(cursor);
  return{text,applied:edits.length};
}
// Add the JSON-file CLI described by the work order without import side effects.
if(process.argv[1]!==undefined&&import.meta.url===pathToFileURL(process.argv[1]).href){
  const fail=(message)=>{
    process.stderr.write(`${message}\n`);
    process.exit(2);
  };
  if(process.argv.length!==3)fail('usage: node patch-transaction.js INPUT_JSON_FILE');
  let raw;
  try{
    raw=readFileSync(process.argv[2],'utf8');
  }catch(error){
    fail(`cannot read input file: ${error.message}`);
  }
  let doc;
  try{
    doc=JSON.parse(raw);
  }catch(error){
    fail(`invalid JSON: ${error.message}`);
  }
  try{
    const result=applyTransaction(typeof doc==='object'&&doc!==null?doc.source:undefined,
      typeof doc==='object'&&doc!==null?doc.edits:undefined);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  }catch(error){
    fail(error.message);
  }
}

