test('CLI success, argument, file, JSON, and transaction failures',()=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-tx-'));
  const okFile=join(dir,'ok.json');
  writeFileSync(okFile,JSON.stringify({note:'ignored',source:'abcdef',
    edits:[edit(0,1,'a','LONG'),edit(3,5,'de','X')]}));
  const good=cli(okFile);
  assert.equal(good.status,0);
  assert.equal(good.stderr,'');
  assert.equal(good.stdout,'{"text":"LONGbcXf","applied":2}\n');
  const emptyFile=join(dir,'empty.json');
  writeFileSync(emptyFile,JSON.stringify({source:'tail\r\n',edits:[]}));
  const empty=cli(emptyFile);
  assert.equal(empty.status,0);
  assert.equal(empty.stderr,'');
  assert.equal(empty.stdout,'{"text":"tail\\r\\n","applied":0}\n');
  const missing=cli(join(dir,'missing.json'));
  assert.equal(missing.status,2);
  assert.equal(missing.stdout,'');
  assert.ok(missing.stderr.length>0);
  const badArgs0=cli();
  assert.equal(badArgs0.status,2);
  assert.equal(badArgs0.stdout,'');
  assert.ok(badArgs0.stderr.length>0);
  const badArgs2=cli(okFile,okFile);
  assert.equal(badArgs2.status,2);
  assert.equal(badArgs2.stdout,'');
  assert.ok(badArgs2.stderr.length>0);
  const badJson=join(dir,'bad.json');
  writeFileSync(badJson,'{source: 1');
  const badJsonOut=cli(badJson);
  assert.equal(badJsonOut.status,2);
  assert.equal(badJsonOut.stdout,'');
  assert.ok(badJsonOut.stderr.length>0);
  const badTx=join(dir,'badtx.json');
  writeFileSync(badTx,JSON.stringify({source:'abc',
    edits:[{start:1,end:1,before:'',after:'x'},{start:1,end:2,before:'b',after:'y'}]}));
  const badTxOut=cli(badTx);
  assert.equal(badTxOut.status,2);
  assert.equal(badTxOut.stdout,'');
  assert.ok(badTxOut.stderr.length>0);
  const badSource=join(dir,'badsrc.json');
  writeFileSync(badSource,JSON.stringify({source:123,edits:[]}));
  const badSourceOut=cli(badSource);
  assert.equal(badSourceOut.status,2);
  assert.equal(badSourceOut.stdout,'');
  assert.ok(badSourceOut.stderr.length>0);
  rmSync(dir,{recursive:true,force:true});
});
test('importing the module does not run the CLI',()=>{
  const dir=mkdtempSync(join(tmpdir(),'patch-tx-import-'));
  const file=join(dir,'ok.json');
  writeFileSync(file,JSON.stringify({source:'abc',edits:[]}));
  const moduleUrl=pathToFileURL(join(fileURLToPath(new URL('..',import.meta.url)),
    'patch-transaction.js')).href;
  const out=execFileSync(process.execPath,
    ['-e',`import{applyTransaction}from'${moduleUrl}';
      console.log(JSON.stringify(applyTransaction('abc',[])));`,
      file],{encoding:'utf8'});
  assert.equal(out,'{"text":"abc","applied":0}\n');
  rmSync(dir,{recursive:true,force:true});
});

